/**
 * iOS launch screens (apple-touch-startup-image).
 *
 * iOS only uses a startup image whose pixel size matches the device exactly,
 * selected by a media query, so every current iPhone and iPad size is listed.
 * Generated by `pnpm icons` (scripts/generate-pwa-icons.mjs) and linked from
 * the root layout's metadata. Dependency-free so the icon script can import it.
 */

/** Paints the splash and the manifest background: the dashboard's first screen. */
export const LAUNCH_BACKGROUND = "#FBFDFF";

type Device = { w: number; h: number; dpr: number; tablet?: boolean };

// CSS-pixel portrait sizes. Several models share a size; each size is listed once.
const DEVICES: Device[] = [
  { w: 440, h: 956, dpr: 3 }, // iPhone 16 Pro Max
  { w: 402, h: 874, dpr: 3 }, // iPhone 16 Pro
  { w: 430, h: 932, dpr: 3 }, // iPhone 16 Plus, 15 Pro Max, 15 Plus, 14 Pro Max
  { w: 393, h: 852, dpr: 3 }, // iPhone 16, 15 Pro, 15, 14 Pro
  { w: 428, h: 926, dpr: 3 }, // iPhone 14 Plus, 13 Pro Max, 12 Pro Max
  { w: 390, h: 844, dpr: 3 }, // iPhone 14, 13, 13 Pro, 12, 12 Pro
  { w: 375, h: 812, dpr: 3 }, // iPhone 13 mini, 12 mini, 11 Pro, XS, X
  { w: 414, h: 896, dpr: 3 }, // iPhone 11 Pro Max, XS Max
  { w: 414, h: 896, dpr: 2 }, // iPhone 11, XR
  { w: 414, h: 736, dpr: 3 }, // iPhone 8 Plus
  { w: 375, h: 667, dpr: 2 }, // iPhone SE (2nd, 3rd), 8
  { w: 320, h: 568, dpr: 2 }, // iPhone SE (1st)
  { w: 1032, h: 1376, dpr: 2, tablet: true }, // iPad Pro 13" (M4)
  { w: 1024, h: 1366, dpr: 2, tablet: true }, // iPad Pro 12.9", iPad Air 13"
  { w: 834, h: 1210, dpr: 2, tablet: true }, // iPad Pro 11" (M4)
  { w: 834, h: 1194, dpr: 2, tablet: true }, // iPad Pro 11"
  { w: 820, h: 1180, dpr: 2, tablet: true }, // iPad Air 11", iPad (10th)
  { w: 834, h: 1112, dpr: 2, tablet: true }, // iPad Air 10.5"
  { w: 810, h: 1080, dpr: 2, tablet: true }, // iPad 10.2"
  { w: 768, h: 1024, dpr: 2, tablet: true }, // iPad 9.7", iPad mini 5
  { w: 744, h: 1133, dpr: 2, tablet: true }, // iPad mini (6th, 7th)
];

export type SplashScreen = {
  url: string;
  media: string;
  /** Device pixels */
  width: number;
  height: number;
  /** Logo edge in device pixels */
  logo: number;
};

function logoSize(d: Device) {
  // Phones: 27% of the screen width. Tablets: capped at 200 CSS px so the
  // mark stays a mark, not a poster.
  const css = d.tablet ? Math.min(200, d.w * 0.22) : d.w * 0.27;
  return Math.round(css * d.dpr);
}

export const SPLASH_SCREENS: SplashScreen[] = DEVICES.flatMap((d) => {
  const orientations = d.tablet ? (["portrait", "landscape"] as const) : (["portrait"] as const);
  return orientations.map((o) => {
    const [cw, ch] = o === "portrait" ? [d.w, d.h] : [d.h, d.w];
    const width = cw * d.dpr;
    const height = ch * d.dpr;
    return {
      url: `/splash/apple-splash-${width}x${height}.png`,
      media:
        `(device-width: ${d.w}px) and (device-height: ${d.h}px) and ` +
        `(-webkit-device-pixel-ratio: ${d.dpr}) and (orientation: ${o})`,
      width,
      height,
      logo: logoSize(d),
    };
  });
});
